export function buildInspectionsSchedule(startISO = null) {
  return buildScheduleFor(INSPECTIONS_MODULES, startISO, INSPECTIONS_META.cadenceDays);
}

export function inspectionsProgressSummary(progress = {}) {
  return progressSummaryFor(INSPECTIONS_MODULES, progress);
}

export function exportInspectionsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: INSPECTIONS_META,
    modules: buildInspectionsSchedule(startISO),
    sessionFlow: INSPECTIONS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function inspectionsRefs() {
  const seen = new Set();
  for (const m of INSPECTIONS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((INSPECTIONS_META.wordFirst && INSPECTIONS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

